#include <Cellerator/compiler/profile/implement_bounded_branch_alternatives_and_joins_v1.hh>
namespace cellerator::compiler::profile::v1 {namespace{bool same(profile_identity_v1 a,profile_identity_v1 b){return a.low==b.low&&a.high==b.high;}bool less(profile_identity_v1 a,profile_identity_v1 b){return a.high<b.high||(a.high==b.high&&a.low<b.low);}}
branch_profile_join_status_v1 join_branch_profiles_v1(const branch_profile_state_v1*in,std::uint32_t n,std::uint32_t limit,branch_profile_set_v1*out) noexcept{if(!out||!in||!n||!limit||!out->states)return branch_profile_join_status_v1::invalid_argument;for(std::uint32_t i=1;i<n;++i)if(!same(in[0].semantic_subject,in[i].semantic_subject))return branch_profile_join_status_v1::subject_mismatch;if(n>limit){if(!out->capacity)return branch_profile_join_status_v1::insufficient_capacity;auto w=in[0];w.state={};w.evidence={};w.flags|=branch_profile_widened_v1;for(std::uint32_t i=1;i<n;++i){w.minimum=in[i].minimum<w.minimum?in[i].minimum:w.minimum;w.maximum=in[i].maximum>w.maximum?in[i].maximum:w.maximum;w.confidence=in[i].confidence<w.confidence?in[i].confidence:w.confidence;}out->states[0]=w;out->count=1;out->maximum_alternatives=limit;return branch_profile_join_status_v1::ok;}if(out->capacity<n)return branch_profile_join_status_v1::insufficient_capacity;out->count=0;for(std::uint32_t i=0;i<n;++i){std::uint32_t at=out->count;while(at&&less(in[i].state,out->states[at-1].state)){out->states[at]=out->states[at-1];--at;}out->states[at]=in[i];++out->count;}out->maximum_alternatives=limit;return branch_profile_join_status_v1::ok;}
}  // namespace cellerator::compiler::profile::v1
